import sys
import csv
import json


def main():
    path = sys.argv[1]
    totals = {}
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        for row in reader:
            if not row:
                continue
            item_field = row[0] if len(row) > 0 else ''
            q_field = row[1] if len(row) > 1 else ''
            name = ' '.join(item_field.split()).casefold()
            if not name:
                continue
            qs = q_field.strip()
            if qs == '':
                q = 1
            else:
                q = int(qs)
            totals[name] = totals.get(name, 0) + q

    result = []
    for name in sorted(totals):
        result.append({'item': name, 'quantity': totals[name]})

    print(json.dumps(result))


if __name__ == '__main__':
    main()
